// ALLE 195 STAATEN DER ERDE (ISO-3166-1 Numeric) – MIT & OHNE GRENZEN SPIELBAR
const COUNTRIES_WORLD_195 = [
  { id: "004", difficulty: "medium", en: "Afghanistan", de: "Afghanistan", factEn: "Afghanistan is a mountainous, landlocked country at the crossroads of Central and South Asia.", factDe: "Afghanistan ist ein gebirgiger Binnenstaat an der Schnittstelle zwischen Zentral- und Südasien." },
  { id: "008", difficulty: "hard", en: "Albania", de: "Albanien", factEn: "Albania lies on the Balkan Peninsula along the Adriatic and Ionian Seas.", factDe: "Albanien liegt auf der Balkanhalbinsel an der Küste des Adriatischen und des Ionischen Meeres." },
  { id: "012", difficulty: "medium", en: "Algeria", de: "Algerien", factEn: "Algeria is the largest country in Africa by land area, with most of its territory covered by the Sahara Desert.", factDe: "Algerien ist flächenmäßig das größte Land Afrikas – der Großteil besteht aus der Sahara." },
  { id: "020", difficulty: "hard", en: "Andorra", de: "Andorra", factEn: "Andorra is a tiny principality nestled high in the eastern Pyrenees mountains between France and Spain.", factDe: "Andorra ist ein kleiner Zwergstaat hoch oben in den östlichen Pyrenäen zwischen Frankreich und Spanien." },
  { id: "024", difficulty: "medium", en: "Angola", de: "Angola", factEn: "Angola is a large resource-rich nation on the Atlantic coast of southern Africa.", factDe: "Angola liegt an der Atlantikküste im südlichen Afrika und verfügt über die Exklave Cabinda." },
  { id: "028", difficulty: "hard", en: "Antigua and Barbuda", de: "Antigua und Barbuda", factEn: "Antigua and Barbuda is a twin-island Caribbean nation famous for having 365 beaches.", factDe: "Der karibische Inselstaat Antigua und Barbuda ist berühmt für seine 365 Strände." },
  { id: "032", difficulty: "easy", en: "Argentina", de: "Argentinien", factEn: "Argentina spans most of the southern half of South America, stretching from the subtropical north to Patagonia.", factDe: "Argentinien erstreckt sich über weite Teile des südlichen Südamerikas bis nach Patagonien." },
  { id: "051", difficulty: "hard", en: "Armenia", de: "Armenien", factEn: "Armenia is a landlocked country in the South Caucasus and was the first nation to adopt Christianity as its state religion in 301 AD.", factDe: "Der Binnenstaat Armenien im Südkaukasus nahm 301 n. Chr. als erstes Land der Welt das Christentum als Staatsreligion an." },
  { id: "036", difficulty: "easy", en: "Australia", de: "Australien", factEn: "Australia is the sixth-largest country in the world and occupies an entire continent.", factDe: "Australien ist das sechstgrößte Land der Erde und nimmt einen kompletten Kontinent ein." },
  { id: "040", difficulty: "medium", en: "Austria", de: "Österreich", factEn: "Roughly two-thirds of landlocked Austria is covered by the Eastern Alps.", factDe: "Rund zwei Drittel der Fläche des Binnenstaates Österreich werden von den Ostalpen eingenommen." },
  { id: "031", difficulty: "hard", en: "Azerbaijan", de: "Aserbaidschan", factEn: "Azerbaijan lies on the western shore of the Caspian Sea and is known as the 'Land of Fire' for its natural gas vents.", factDe: "Aserbaidschan liegt am Westufer des Kaspischen Meeres und trägt wegen seiner Erdgasfeuer den Beinamen ‚Land des Feuers‘." },
  { id: "044", difficulty: "hard", en: "Bahamas", de: "Bahamas", factEn: "The Bahamas is an archipelago of more than 3,000 islands, cays, and islets in the Atlantic Ocean southeast of Florida.", factDe: "Die Bahamas bestehen aus über 3.000 Inseln und Korallenriffen im Atlantik südöstlich von Florida." },
  { id: "048", difficulty: "hard", en: "Bahrain", de: "Bahrain", factEn: "Bahrain is an island kingdom in the Persian Gulf connected to Saudi Arabia by the King Fahd Causeway.", factDe: "Das Insel-Königreich Bahrain im Persischen Golf ist über einen 25 Kilometer langen Damm mit Saudi-Arabien verbunden." },
  { id: "050", difficulty: "medium", en: "Bangladesh", de: "Bangladesch", factEn: "Bangladesh sits on the fertile Ganges-Brahmaputra delta and has one of the highest population densities on Earth.", factDe: "Bangladesch liegt im fruchtbaren Mündungsdelta von Ganges und Brahmaputra am Golf von Bengalen." },
  { id: "052", difficulty: "hard", en: "Barbados", de: "Barbados", factEn: "Barbados is the easternmost island nation of the Caribbean Lesser Antilles.", factDe: "Barbados ist der östlichste Inselstaat der Kleinen Antillen in der Karibik." },
  { id: "112", difficulty: "medium", en: "Belarus", de: "Belarus (Weißrussland)", factEn: "Belarus is a landlocked Eastern European country bordered by Russia, Ukraine, Poland, Lithuania, and Latvia.", factDe: "Der osteuropäische Binnenstaat Belarus grenzt an Russland, die Ukraine, Polen, Litauen und Lettland." },
  { id: "056", difficulty: "medium", en: "Belgium", de: "Belgien", factEn: "Belgium has three official languages—Dutch, French, and German—and hosts the main institutions of the European Union.", factDe: "Belgien hat drei Amtssprachen (Niederländisch, Französisch, Deutsch) und beherbergt den Hauptsitz der EU." },
  { id: "084", difficulty: "hard", en: "Belize", de: "Belize", factEn: "Belize is the only Central American country whose official language is English.", factDe: "Belize liegt an der Karibikküste Mittelamerikas und ist das einzige Land der Region mit Englisch als Amtssprache." },
  { id: "204", difficulty: "hard", en: "Benin", de: "Benin", factEn: "Benin is a narrow West African country stretching north from the Gulf of Guinea to the Niger River.", factDe: "Der schmale westafrikanische Staat Benin reicht vom Golf von Guinea bis an den Fluss Niger." },
  { id: "064", difficulty: "hard", en: "Bhutan", de: "Bhutan", factEn: "Tucked in the eastern Himalayas between China and India, Bhutan measures national progress using Gross National Happiness.", factDe: "Das Königreich Bhutan liegt im östlichen Himalaya zwischen Indien und China und misst seinen Wohlstand am Bruttonationalglück." },
  { id: "068", difficulty: "medium", en: "Bolivia", de: "Bolivien", factEn: "Bolivia is one of only two landlocked countries in South America and is home to the high-altitude Altiplano plateau.", factDe: "Bolivien ist neben Paraguay der einzige Binnenstaat Südamerikas und beherbergt den über 4.000 Meter hoch gelegenen Titicacasee." },
  { id: "070", difficulty: "hard", en: "Bosnia and Herzegovina", de: "Bosnien und Herzegowina", factEn: "Bosnia and Herzegovina is a Balkan nation with a tiny 20-kilometer coastline on the Adriatic Sea at Neum.", factDe: "Bosnien und Herzegowina liegt auf dem Balkan und besitzt bei Neum nur einen rund 20 Kilometer breiten Zugang zur Adria." },
  { id: "072", difficulty: "hard", en: "Botswana", de: "Botsuana", factEn: "Landlocked Botswana is home to the vast Okavango Delta and much of the Kalahari Desert.", factDe: "Der Binnenstaat Botsuana im südlichen Afrika behergt das riesige Okavangodelta und weite Teile der Kalahari." },
  { id: "076", difficulty: "easy", en: "Brazil", de: "Brasilien", factEn: "Brazil covers nearly half of South America and contains the majority of the Amazon rainforest.", factDe: "Brasilien nimmt fast die Hälfte Südamerikas ein und beherbergt den größten Teil des Amazonas-Regenwalds." },
  { id: "096", difficulty: "hard", en: "Brunei", de: "Brunei", factEn: "Brunei is a small, oil-rich sultanate divided into two parts on the northern coast of the island of Borneo.", factDe: "Das kleine Sultanat Brunei liegt an der Nordküste der Insel Borneo und besteht aus zwei voneinander getrennten Gebietsteilen." },
  { id: "100", difficulty: "medium", en: "Bulgaria", de: "Bulgarien", factEn: "Bulgaria lies in southeastern Europe along the western coast of the Black Sea.", factDe: "Bulgarien liegt in Südosteuropa an der Westküste des Schwarzen Meeres." },
  { id: "854", difficulty: "hard", en: "Burkina Faso", de: "Burkina Faso", factEn: "Burkina Faso is a landlocked West African country situated in the Sahel region.", factDe: "Burkina Faso ist ein Binnenstaat in Westafrika am Übergang zur Sahelzone." },
  { id: "108", difficulty: "hard", en: "Burundi", de: "Burundi", factEn: "Burundi is a small, densely populated country in the African Great Lakes region bordering Lake Tanganyika.", factDe: "Burundi ist ein kleiner, dicht besiedelter Binnenstaat am Tanganjikasee in Ostafrika." },
  { id: "132", difficulty: "hard", en: "Cabo Verde", de: "Kap Verde", factEn: "Cabo Verde is a volcanic archipelago of 10 islands in the central Atlantic Ocean off the coast of Senegal.", factDe: "Kap Verde ist ein vulkanischer Inselstaat aus zehn Hauptinseln im Zentralatlantik vor der Küste Senegals." },
  { id: "116", difficulty: "hard", en: "Cambodia", de: "Kambodscha", factEn: "Cambodia is home to Angkor Wat, the largest religious monument in the world.", factDe: "Kambodscha liegt in Südostasien und beherbergt mit Angkor Wat die größte Tempelanlage der Welt." },
  { id: "120", difficulty: "hard", en: "Cameroon", de: "Kamerun", factEn: "Often called 'Africa in miniature', Cameroon features beaches, deserts, mountains, rainforests, and savannas.", factDe: "Kamerun liegt am Übergang zwischen West- und Zentralafrika und vereint Küsten, Regenwald, Savannen und Hochgebirge." },
  { id: "124", difficulty: "easy", en: "Canada", de: "Kanada", factEn: "Canada is the second-largest country in the world by total area and has the longest coastline of any nation.", factDe: "Kanada ist das zweitgrößte Land der Erde und besitzt die längste Küstenlinie aller Staaten." },
  { id: "140", difficulty: "hard", en: "Central African Republic", de: "Zentralafrikanische Republik", factEn: "As its name suggests, the Central African Republic is a landlocked nation in the geographic heart of Africa.", factDe: "Die Zentralafrikanische Republik ist ein großer Binnenstaat im geografischen Zentrum des afrikanischen Kontinents." },
  { id: "148", difficulty: "hard", en: "Chad", de: "Tschad", factEn: "Chad is a landlocked nation in north-central Africa named after Lake Chad.", factDe: "Der Binnenstaat Tschad liegt im nördlichen Zentralafrika und wurde nach dem Tschadsee benannt." },
  { id: "152", difficulty: "medium", en: "Chile", de: "Chile", factEn: "Chile forms a long, narrow ribbon of land between the Andes mountains and the Pacific Ocean.", factDe: "Chile bildet einen über 4.300 Kilometer langen, schmalen Küstenstreifen zwischen den Anden und dem Pazifik." },
  { id: "156", difficulty: "easy", en: "China", de: "China", factEn: "China is the fourth-largest country by area and spans five geographic time zones under a single standard time.", factDe: "China erstreckt sich über fünf geografische Zeitzonen, nutzt landesweit aber nur eine einheitliche Standardzeit." },
  { id: "170", difficulty: "medium", en: "Colombia", de: "Kolumbien", factEn: "Colombia sits at the northwestern tip of South America and borders both the Pacific Ocean and the Caribbean Sea.", factDe: "Kolumbien liegt im Nordwesten Südamerikas und grenzt sowohl an den Pazifik als auch an die Karibik." },
  { id: "174", difficulty: "hard", en: "Comoros", de: "Komoren", factEn: "The Comoros is a volcanic archipelago located in the Mozambique Channel between Madagascar and mainland Africa.", factDe: "Die Komoren sind ein vulkanischer Inselstaat im Indischen Ozean zwischen Madagaskar und Mosambik." },
  { id: "178", difficulty: "hard", en: "Republic of the Congo", de: "Republik Kongo", factEn: "The Republic of the Congo lies along the equator in Central Africa, northwest of the Congo River.", factDe: "Die Republik Kongo (Kongo-Brazzaville) liegt am Äquator nordwestlich des Kongo-Flusses." },
  { id: "180", difficulty: "medium", en: "Democratic Republic of the Congo", de: "Demokratische Republik Kongo", factEn: "The DR Congo is the second-largest country in Africa by area, with only a tiny 37-kilometer Atlantic coastline.", factDe: "Die Demokratische Republik Kongo ist das zweitgrößte Land Afrikas, hat aber nur einen 37 Kilometer schmalen Zugang zum Atlantik." },
  { id: "188", difficulty: "medium", en: "Costa Rica", de: "Costa Rica", factEn: "Costa Rica sits on the Central American isthmus between Nicaragua and Panama and abolished its army in 1948.", factDe: "Costa Rica liegt in Mittelamerika zwischen Nicaragua und Panama und schaffte 1948 sein stehendes Heer ab." },
  { id: "384", difficulty: "hard", en: "Côte d'Ivoire", de: "Elfenbeinküste", factEn: "Côte d'Ivoire (Ivory Coast) is a West African nation and the world's largest producer and exporter of cocoa beans.", factDe: "Die Elfenbeinküste (Côte d’Ivoire) liegt am Golf von Guinea und ist der weltweit größte Produzent von Kakaobohnen." },
  { id: "191", difficulty: "medium", en: "Croatia", de: "Kroatien", factEn: "Croatia's croissant-shaped territory includes more than a thousand islands along the Adriatic Sea.", factDe: "Kroatien besitzt eine markante hufeisenförmige Landesform und über tausend Inseln in der Adria." },
  { id: "192", difficulty: "easy", en: "Cuba", de: "Kuba", factEn: "Cuba is the largest island nation in the Caribbean, situated at the entrance to the Gulf of Mexico.", factDe: "Kuba ist der größte Inselstaat der Karibik und liegt am Eingang zum Golf von Mexiko." },
  { id: "196", difficulty: "hard", en: "Cyprus", de: "Zypern", factEn: "Cyprus is the third-largest island in the Mediterranean Sea, located south of Turkey and west of Syria.", factDe: "Zypern ist die drittgrößte Insel des Mittelmeers und liegt im östlichen Mittelmeer südlich der Türkei." },
  { id: "203", difficulty: "medium", en: "Czechia", de: "Tschechien", factEn: "Czechia (the Czech Republic) is a landlocked Central European country bordered by Germany, Austria, Slovakia, and Poland.", factDe: "Tschechien ist ein mitteleuropäischer Binnenstaat, der an Deutschland, Österreich, die Slowakei und Polen grenzt." },
  { id: "208", difficulty: "medium", en: "Denmark", de: "Dänemark", factEn: "Denmark occupies the Jutland Peninsula and more than 400 islands between the North Sea and the Baltic Sea.", factDe: "Dänemark erstreckt sich über die Halbinsel Jütland und über 400 Inseln zwischen Nord- und Ostsee." },
  { id: "262", difficulty: "hard", en: "Djibouti", de: "Dschibuti", factEn: "Djibouti sits on the Horn of Africa at the strategic Bab-el-Mandeb Strait connecting the Red Sea and the Indian Ocean.", factDe: "Dschibuti liegt am Horn von Afrika an der strategisch wichtigen Meerenge Bab al-Mandab zwischen Rotem Meer und Indischem Ozean." },
  { id: "212", difficulty: "hard", en: "Dominica", de: "Dominica", factEn: "Nicknamed the 'Nature Island of the Caribbean', Dominica is a mountainous volcanic island between Guadeloupe and Martinique.", factDe: "Dominica ist eine gebirgige Vulkaninsel der Kleinen Antillen zwischen Guadeloupe und Martinique." },
  { id: "214", difficulty: "hard", en: "Dominican Republic", de: "Dominikanische Republik", factEn: "The Dominican Republic occupies the eastern five-eighths of the Caribbean island of Hispaniola, sharing it with Haiti.", factDe: "Die Dominikanische Republik nimmt die östlichen zwei Drittel der Karibikinsel Hispaniola ein." },
  { id: "218", difficulty: "medium", en: "Ecuador", de: "Ecuador", factEn: "Named after the equator that runs right through it, Ecuador also governs the Galápagos Islands in the Pacific.", factDe: "Benannt nach dem Äquator, der das Land durchquert, gehören zu Ecuador auch die Galápagos-Inseln im Pazifik." },
  { id: "818", difficulty: "easy", en: "Egypt", de: "Ägypten", factEn: "Egypt connects northeast Africa with the Middle East via the Sinai Peninsula.", factDe: "Ägypten verbindet Nordostafrika über die Sinai-Halbinsel mit Vorderasien." },
  { id: "222", difficulty: "hard", en: "El Salvador", de: "El Salvador", factEn: "El Salvador is the smallest and most densely populated country in Central America, bordering only the Pacific Ocean.", factDe: "El Salvador ist das kleinste Land Mittelamerikas und besitzt als einziger Staat der Region keine Karibikküste." },
  { id: "226", difficulty: "hard", en: "Equatorial Guinea", de: "Äquatorialguinea", factEn: "Equatorial Guinea consists of a mainland territory (Río Muni) and islands including Bioko, where its capital Malabo sits.", factDe: "Äquatorialguinea besteht aus einem Festlandteil an der westafrikanischen Küste und mehreren Inseln wie Bioko." },
  { id: "232", difficulty: "hard", en: "Eritrea", de: "Eritrea", factEn: "Eritrea stretches for more than 1,100 kilometers along the Red Sea coast in the Horn of Africa.", factDe: "Eritrea erstreckt sich über mehr als 1.100 Kilometer entlang der Küste des Roten Meeres in Ostafrika." },
  { id: "233", difficulty: "medium", en: "Estonia", de: "Estland", factEn: "Estonia is the northernmost of the three Baltic states and includes more than 2,000 islands in the Baltic Sea.", factDe: "Estland ist der nördlichste der drei baltischen Staaten und umfasst über 2.000 Inseln in der Ostsee." },
  { id: "748", difficulty: "hard", en: "Eswatini", de: "Eswatini", factEn: "Formerly known as Swaziland, Eswatini is a small landlocked kingdom surrounded by South Africa and Mozambique.", factDe: "Das kleine Königreich Eswatini (früher Swasiland) ist ein Binnenstaat zwischen Südafrika und Mosambik." },
  { id: "231", difficulty: "medium", en: "Ethiopia", de: "Äthiopien", factEn: "Ethiopia is the most populous landlocked country in the world, located in the Horn of Africa.", factDe: "Äthiopien liegt am Horn von Afrika und ist mit über 120 Millionen Einwohnern der bevölkerungsreichste Binnenstaat der Erde." },
  { id: "242", difficulty: "hard", en: "Fiji", de: "Fidschi", factEn: "Fiji is a South Pacific archipelago of more than 300 islands, crossed by the 180th meridian.", factDe: "Fidschi ist ein Inselstaat im Südpazifik aus über 300 Inseln, durch den der 180. Längengrad verläuft." },
  { id: "246", difficulty: "easy", en: "Finland", de: "Finnland", factEn: "Finland lies in Northern Europe between Sweden and Russia, with roughly a quarter of its territory north of the Arctic Circle.", factDe: "Finnland liegt in Nordeuropa zwischen Schweden und Russland – rund ein Viertel des Landes liegt nördlich des Polarkreises." },
  { id: "250", difficulty: "easy", en: "France", de: "Frankreich", factEn: "Metropolitan France is often nicknamed 'L'Hexagone' because of its roughly six-sided geometric outline.", factDe: "Das europäische Kernland Frankreichs wird wegen seiner sechseckigen Umrisse oft ‚L’Hexagone‘ genannt." },
  { id: "266", difficulty: "hard", en: "Gabon", de: "Gabun", factEn: "Gabon sits astride the equator on Africa's Atlantic coast, with nearly 85% of the country covered by rainforest.", factDe: "Gabun liegt am Äquator an der Atlantikküste Zentralafrikas und ist zu rund 85 % von tropischem Regenwald bedeckt." },
  { id: "270", difficulty: "hard", en: "Gambia", de: "Gambia", factEn: "The Gambia is the smallest country on mainland Africa, snaking narrowly along both banks of the Gambia River inside Senegal.", factDe: "Gambia ist der kleinste Flächenstaat auf dem afrikanischen Festland und zieht sich schmal entlang des Gambia-Flusses mitten durch Senegal." },
  { id: "268", difficulty: "hard", en: "Georgia", de: "Georgien", factEn: "Georgia lies at the intersection of Eastern Europe and Western Asia, bordered by the Black Sea and the Caucasus Mountains.", factDe: "Georgien liegt am Schwarzen Meer und am Großen Kaukasus an der Grenze zwischen Osteuropa und Vorderasien." },
  { id: "276", difficulty: "easy", en: "Germany", de: "Deutschland", factEn: "Located in the heart of Central Europe, Germany borders nine countries and has coastlines on both the North and Baltic Seas.", factDe: "Deutschland liegt im Zentrum Mitteleuropas, grenzt an neun Nachbarstaaten und hat Küsten an Nord- und Ostsee." },
  { id: "288", difficulty: "hard", en: "Ghana", de: "Ghana", factEn: "Ghana sits on the Gulf of Guinea in West Africa and contains Lake Volta, one of the largest artificial reservoirs by surface area.", factDe: "Ghana liegt am Golf von Guinea in Westafrika und beherbergt den Voltasee, einen der flächenmäßig größten Stauseen der Erde." },
  { id: "300", difficulty: "easy", en: "Greece", de: "Griechenland", factEn: "Located at the southern tip of the Balkans, Greece has thousands of islands scattered across the Aegean and Ionian Seas.", factDe: "Griechenland liegt an der Südspitze der Balkanhalbinsel und umfasst tausende Inseln in der Ägäis und im Ionischen Meer." },
  { id: "308", difficulty: "hard", en: "Grenada", de: "Grenada", factEn: "Known as the 'Island of Spice' for its nutmeg production, Grenada lies at the southern end of the Grenadines in the Caribbean.", factDe: "Die Karibikinsel Grenada liegt nördlich von Trinidad und Tobago und trägt wegen ihres Muskatnuss-Anbaus den Beinamen ‚Gewürzinsel‘." },
  { id: "320", difficulty: "hard", en: "Guatemala", de: "Guatemala", factEn: "Guatemala borders Mexico to the north and west and has coastlines on both the Pacific Ocean and the Caribbean Sea.", factDe: "Guatemala grenzt im Norden und Westen an Mexiko und besitzt Küsten am Pazifik sowie an der Karibik." },
  { id: "324", difficulty: "hard", en: "Guinea", de: "Guinea", factEn: "Guinea lies on the Atlantic coast of West Africa and is the source of the Niger, Gambia, and Senegal rivers.", factDe: "Guinea liegt an der westafrikanischen Atlantikküste – im Hochland von Fouta Djallon entspringen die großen Flüsse Niger, Gambia und Senegal." },
  { id: "624", difficulty: "hard", en: "Guinea-Bissau", de: "Guinea-Bissau", factEn: "Guinea-Bissau is a small West African country between Senegal and Guinea that includes the Bijagós Archipelago.", factDe: "Guinea-Bissau liegt an der Atlantikküste Westafrikas zwischen Senegal und Guinea und umfasst auch den Bissagos-Archipel." },
  { id: "328", difficulty: "hard", en: "Guyana", de: "Guyana", factEn: "Located on South America's northern Atlantic coast, Guyana is the only South American country with English as its official language.", factDe: "Guyana liegt an der Nordküste Südamerikas und ist das einzige Land des Kontinents mit Englisch als Amtssprache." },
  { id: "332", difficulty: "hard", en: "Haiti", de: "Haiti", factEn: "Haiti occupies the western three-eighths of the Caribbean island of Hispaniola, west of the Dominican Republic.", factDe: "Haiti nimmt das westliche Drittel der Karibikinsel Hispaniola ein und grenzt im Osten an die Dominikanische Republik." },
  { id: "340", difficulty: "hard", en: "Honduras", de: "Honduras", factEn: "Honduras sits in the heart of Central America, bordering Guatemala, El Salvador, and Nicaragua.", factDe: "Honduras liegt in Mittelamerika mit einer langen Karibikküste im Norden und einem schmalen Zugang zum Pazifik im Süden." },
  { id: "348", difficulty: "medium", en: "Hungary", de: "Ungarn", factEn: "Hungary is a landlocked country in the Carpathian Basin of Central Europe, bisected by the Danube River.", factDe: "Ungarn ist ein Binnenstaat im Pannonischen Becken Mitteleuropas und wird von der Donau durchflossen." },
  { id: "352", difficulty: "easy", en: "Iceland", de: "Island", factEn: "Iceland is a Nordic island nation in the North Atlantic sitting directly atop the Mid-Atlantic Ridge.", factDe: "Island ist ein vulkanischer Inselstaat im Nordatlantik direkt auf dem Mittelatlantischen Rücken kurz südlich des Polarkreises." },
  { id: "356", difficulty: "easy", en: "India", de: "Indien", factEn: "India forms a massive peninsula in South Asia jutting into the Indian Ocean between the Arabian Sea and the Bay of Bengal.", factDe: "Indien bildet eine riesige Halbinsel in Südasien zwischen dem Arabischen Meer und dem Golf von Bengalen." },
  { id: "360", difficulty: "easy", en: "Indonesia", de: "Indonesien", factEn: "Indonesia straddles the equator between the Indian and Pacific Oceans across more than 17,000 islands.", factDe: "Indonesien erstreckt sich beiderseits des Äquators über mehr als 17.000 Inseln zwischen Indischem und Pazifischem Ozean." },
  { id: "364", difficulty: "medium", en: "Iran", de: "Iran", factEn: "Iran lies in Western Asia between the Caspian Sea to the north and the Persian Gulf and Gulf of Oman to the south.", factDe: "Der Iran liegt in Vorderasien zwischen dem Kaspischen Meer im Norden und dem Persischen Golf im Süden." },
  { id: "368", difficulty: "medium", en: "Iraq", de: "Irak", factEn: "Historically known as Mesopotamia, Iraq is defined by the Tigris and Euphrates rivers and has a narrow outlet to the Persian Gulf.", factDe: "Der Irak umfasst das historische Zweistromland entlang von Euphrat und Tigris und besitzt im Süden einen schmalen Zugang zum Persischen Golf." },
  { id: "372", difficulty: "easy", en: "Ireland", de: "Irland", factEn: "The Republic of Ireland covers roughly five-sixths of the island of Ireland in the North Atlantic, west of Great Britain.", factDe: "Die Republik Irland nimmt rund fünf Sechstel der Insel Irland westlich von Großbritannien ein." },
  { id: "376", difficulty: "medium", en: "Israel", de: "Israel", factEn: "Israel lies on the southeastern shore of the Mediterranean Sea and borders the Dead Sea, the lowest land elevation on Earth.", factDe: "Israel liegt an der Südostküste des Mittelmeers und grenzt im Osten an das Tote Meer, den tiefsten Punkt der Erdoberfläche." },
  { id: "380", difficulty: "easy", en: "Italy", de: "Italien", factEn: "Italy's boot-shaped peninsula extends into the central Mediterranean Sea and includes the large islands of Sicily and Sardinia.", factDe: "Italiens stiefelförmige Halbinsel ragt weit ins zentrale Mittelmeer hinein und umfasst auch die großen Inseln Sizilien und Sardinien." },
  { id: "388", difficulty: "medium", en: "Jamaica", de: "Jamaika", factEn: "Jamaica is the third-largest island in the Greater Antilles of the Caribbean Sea, located south of Cuba.", factDe: "Jamaika liegt im Karibischen Meer südlich von Kuba und ist die drittgrößte Insel der Großen Antillen." },
  { id: "392", difficulty: "easy", en: "Japan", de: "Japan", factEn: "Japan is a stratovolcanic island arc stretching along the Pacific coast of East Asia.", factDe: "Japan ist ein langgezogener Inselstaat im Pazifik vor der Ostküste Asiens." },
  { id: "400", difficulty: "medium", en: "Jordan", de: "Jordanien", factEn: "Jordan is a mostly desert kingdom in the Middle East with a short Red Sea coastline at the Gulf of Aqaba.", factDe: "Jordanien liegt im Nahen Osten und besitzt am Golf von Akaba einen rund 26 Kilometer kurzen Zugang zum Roten Meer." },
  { id: "398", difficulty: "medium", en: "Kazakhstan", de: "Kasachstan", factEn: "Kazakhstan is the world's largest landlocked country, stretching from the Caspian Sea in the west to the Altai Mountains in the east.", factDe: "Kasachstan ist der größte Binnenstaat der Erde und reicht vom Kaspischen Meer im Westen bis zum Altai-Gebirge im Osten." },
  { id: "404", difficulty: "medium", en: "Kenya", de: "Kenia", factEn: "Kenya lies on the equator along the Indian Ocean coast of East Africa and borders Lake Victoria to the west.", factDe: "Kenia liegt am Äquator an der ostafrikanischen Küste des Indischen Ozeans und grenzt im Westen an den Victoriasee." },
  { id: "296", difficulty: "hard", en: "Kiribati", de: "Kiribati", factEn: "Kiribati is a Pacific island nation spread across 33 atolls and is the only country situated in all four hemispheres.", factDe: "Der pazifische Inselstaat Kiribati erstreckt sich über 33 Atolle und liegt als einziges Land der Welt auf allen vier Erdhalbkugeln." },
  { id: "408", difficulty: "medium", en: "North Korea", de: "Nordkorea", factEn: "North Korea occupies the northern half of the Korean Peninsula, bordering China, Russia, and South Korea.", factDe: "Nordkorea nimmt die nördliche Hälfte der Koreanischen Halbinsel ein und grenzt an China, Russland und Südkorea." },
  { id: "410", difficulty: "easy", en: "South Korea", de: "Südkorea", factEn: "South Korea occupies the southern half of the Korean Peninsula between the Yellow Sea and the Sea of Japan.", factDe: "Südkorea liegt auf der südlichen Hälfte der Koreanischen Halbinsel zwischen Gelbem Meer und Japanischem Meer." },
  { id: "414", difficulty: "hard", en: "Kuwait", de: "Kuwait", factEn: "Kuwait is a small, oil-rich emirate tucked into the northwestern corner of the Persian Gulf between Iraq and Saudi Arabia.", factDe: "Kuwait liegt an der Nordwestspitze des Persischen Golfs zwischen dem Irak und Saudi-Arabien." },
  { id: "417", difficulty: "hard", en: "Kyrgyzstan", de: "Kirgisistan", factEn: "Kyrgyzstan is a mountainous, landlocked country in Central Asia dominated by the Tian Shan mountain range.", factDe: "Kirgisistan ist ein gebirgiger Binnenstaat in Zentralasien, der vom Tian-Shan-Gebirge geprägt wird." },
  { id: "418", difficulty: "hard", en: "Laos", de: "Laos", factEn: "Laos is the only landlocked country in Southeast Asia, bordered by Myanmar, China, Vietnam, Cambodia, and Thailand.", factDe: "Laos ist der einzige Binnenstaat Südostasiens und wird unter anderem vom Fluss Mekong durchzogen." },
  { id: "428", difficulty: "medium", en: "Latvia", de: "Lettland", factEn: "Latvia sits in the center of the three Baltic states along the eastern shore of the Baltic Sea and the Gulf of Riga.", factDe: "Lettland liegt in der Mitte der drei baltischen Staaten an der Ostsee und der Bucht von Riga." },
  { id: "422", difficulty: "hard", en: "Lebanon", de: "Libanon", factEn: "Lebanon is a small, mountainous country on the eastern shore of the Mediterranean Sea between Syria and Israel.", factDe: "Der Libanon liegt an der Ostküste des Mittelmeers zwischen Syrien und Israel." },
  { id: "426", difficulty: "hard", en: "Lesotho", de: "Lesotho", factEn: "Lesotho is a high-altitude kingdom completely enclaved within South Africa—the largest independent enclave in the world.", factDe: "Das gebirgige Königreich Lesotho wird vollständig von Südafrika umschlossen und ist die größte Enklave der Welt." },
  { id: "430", difficulty: "hard", en: "Liberia", de: "Liberia", factEn: "Liberia lies on the West African coast between Sierra Leone and Côte d'Ivoire and is Africa's oldest modern republic.", factDe: "Liberia liegt an der westafrikanischen Atlantikküste zwischen Sierra Leone und der Elfenbeinküste." },
  { id: "434", difficulty: "medium", en: "Libya", de: "Libyen", factEn: "Libya lies in North Africa along the Mediterranean Sea, with over 90% of the country covered by the Sahara Desert.", factDe: "Libyen liegt in Nordafrika an der Mittelmeerküste und besteht zu über 90 % aus Wüstengebieten der Sahara." },
  { id: "438", difficulty: "hard", en: "Liechtenstein", de: "Liechtenstein", factEn: "Liechtenstein is a tiny Alpine principality between Switzerland and Austria—one of only two doubly landlocked countries in the world.", factDe: "Liechtenstein liegt im Alpenrheintal zwischen der Schweiz und Österreich und ist einer von nur zwei doppelten Binnenstaaten der Welt." },
  { id: "440", difficulty: "medium", en: "Lithuania", de: "Litauen", factEn: "Lithuania is the southernmost of the three Baltic states and borders the Baltic Sea, Latvia, Belarus, Poland, and Russia.", factDe: "Litauen ist der südlichste der drei baltischen Staaten und grenzt an die Ostsee, Lettland, Belarus, Polen und Russland." },
  { id: "442", difficulty: "hard", en: "Luxembourg", de: "Luxemburg", factEn: "Luxembourg is a small landlocked Grand Duchy bordered by Belgium, France, and Germany.", factDe: "Das Großherzogtum Luxemburg ist ein kleiner Binnenstaat zwischen Belgien, Frankreich und Deutschland." },
  { id: "450", difficulty: "medium", en: "Madagascar", de: "Madagaskar", factEn: "Located off the southeastern coast of Africa, Madagascar is the fourth-largest island in the world.", factDe: "Madagaskar liegt vor der Südostküste Afrikas im Indischen Ozean und ist die viertgrößte Insel der Erde." },
  { id: "454", difficulty: "hard", en: "Malawi", de: "Malawi", factEn: "Malawi is a landlocked country in southeastern Africa defined by the Great Rift Valley and enormous Lake Malawi.", factDe: "Der Binnenstaat Malawi im südöstlichen Afrika wird maßgeblich vom langgestreckten Malawisee geprägt." },
  { id: "458", difficulty: "medium", en: "Malaysia", de: "Malaysia", factEn: "Malaysia is split between Peninsular Malaysia on the Asian mainland and East Malaysia on the island of Borneo.", factDe: "Malaysia besteht aus zwei Landesteilen: der Malaiischen Halbinsel auf dem Festland und Ost-Malaysia auf der Insel Borneo." },
  { id: "462", difficulty: "hard", en: "Maldives", de: "Malediven", factEn: "The Maldives is an archipelagic nation of 26 coral atolls in the Indian Ocean and is the lowest-lying country on Earth.", factDe: "Die Malediven bestehen aus 26 Korallenatollen im Indischen Ozean und sind der flachste Staat der Erde." },
  { id: "466", difficulty: "hard", en: "Mali", de: "Mali", factEn: "Mali is a large landlocked country in West Africa spanning the Sahara Desert and the Sahel.", factDe: "Mali ist ein großer Binnenstaat in Westafrika, dessen Norden tief in der Sahara liegt." },
  { id: "470", difficulty: "hard", en: "Malta", de: "Malta", factEn: "Malta is a small Mediterranean island nation located between Sicily and the coast of North Africa.", factDe: "Malta ist ein kleiner Inselstaat im zentralen Mittelmeer südlich von Sizilien." },
  { id: "584", difficulty: "hard", en: "Marshall Islands", de: "Marshallinseln", factEn: "The Marshall Islands is a Micronesian chain of volcanic islands and coral atolls in the central Pacific Ocean.", factDe: "Die Marshallinseln sind ein mikronesischer Inselstaat aus über 1.000 Koralleninseln und Atollen im Zentralpazifik." },
  { id: "478", difficulty: "hard", en: "Mauritania", de: "Mauretanien", factEn: "Mauritania bridges the Arab Maghreb and West Africa, with roughly 90% of its land lying within the Sahara.", factDe: "Mauretanien liegt an der Atlantikküste Nordwestafrikas und besteht zu rund 90 % aus der Sahara." },
  { id: "480", difficulty: "hard", en: "Mauritius", de: "Mauritius", factEn: "Mauritius is a volcanic island nation in the Indian Ocean located roughly 900 kilometers east of Madagascar.", factDe: "Der Inselstaat Mauritius liegt im Indischen Ozean rund 900 Kilometer östlich von Madagaskar." },
  { id: "484", difficulty: "easy", en: "Mexico", de: "Mexiko", factEn: "Mexico sits between the United States and Central America, bordered by the Pacific Ocean and the Gulf of Mexico.", factDe: "Mexiko liegt im südlichen Nordamerika zwischen den USA und Mittelamerika an Pazifik und Golf von Mexiko." },
  { id: "583", difficulty: "hard", en: "Micronesia", de: "Mikronesien", factEn: "The Federated States of Micronesia comprises more than 600 islands spread across the western Pacific Ocean.", factDe: "Die Föderierten Staaten von Mikronesien umfassen über 600 Inseln im westlichen Pazifik." },
  { id: "498", difficulty: "hard", en: "Moldova", de: "Republik Moldau", factEn: "Moldova is a landlocked Eastern European country tucked between Romania and Ukraine.", factDe: "Die Republik Moldau ist ein osteuropäischer Binnenstaat zwischen Rumänien und der Ukraine." },
  { id: "492", difficulty: "hard", en: "Monaco", de: "Monaco", factEn: "Located on the French Riviera, Monaco is the second-smallest independent state in the world after Vatican City.", factDe: "Das Fürstentum Monaco an der Côte d’Azur ist nach der Vatikanstadt der zweitkleinste Staat der Erde." },
  { id: "496", difficulty: "medium", en: "Mongolia", de: "Mongolei", factEn: "Sandwiched between Russia and China, Mongolia is the most sparsely populated sovereign nation in the world.", factDe: "Die Mongolei liegt als Binnenstaat zwischen Russland und China und ist der am dünnsten besiedelte Flächenstaat der Erde." },
  { id: "499", difficulty: "hard", en: "Montenegro", de: "Montenegro", factEn: "Montenegro is a rugged Balkan country with a scenic coastline along the Adriatic Sea.", factDe: "Montenegro liegt auf der westlichen Balkanhalbinsel an der Adriaküste." },
  { id: "504", difficulty: "medium", en: "Morocco", de: "Marokko", factEn: "Morocco sits at the northwestern corner of Africa, bordering both the Atlantic Ocean and the Mediterranean Sea.", factDe: "Marokko liegt im äußersten Nordwesten Afrikas und grenzt an den Atlantik sowie das Mittelmeer." },
  { id: "508", difficulty: "hard", en: "Mozambique", de: "Mosambik", factEn: "Mozambique stretches along the southeastern coast of Africa across from Madagascar.", factDe: "Mosambik erstreckt sich über mehr als 2.400 Kilometer entlang der Südostküste Afrikas gegenüber von Madagaskar." },
  { id: "104", difficulty: "hard", en: "Myanmar", de: "Myanmar", factEn: "Myanmar (formerly Burma) is the largest country in mainland Southeast Asia, bordering the Bay of Bengal and Andaman Sea.", factDe: "Myanmar (früher Birma) liegt in Südostasien am Golf von Bengalen und grenzt unter anderem an Indien, China und Thailand." },
  { id: "516", difficulty: "medium", en: "Namibia", de: "Namibia", factEn: "Located on the Atlantic coast of southwestern Africa, Namibia is named after the ancient Namib Desert.", factDe: "Namibia liegt an der Atlantikküste im südwestlichen Afrika und wurde nach der Küstenwüste Namib benannt." },
  { id: "520", difficulty: "hard", en: "Nauru", de: "Nauru", factEn: "Nauru is a tiny oval island nation in Micronesia—the smallest island country and smallest republic in the world.", factDe: "Nauru ist ein winziger Inselstaat im Pazifik und nach Fläche die kleinste Republik der Welt." },
  { id: "524", difficulty: "medium", en: "Nepal", de: "Nepal", factEn: "Landlocked between China and India, Nepal contains eight of the world's ten highest mountains, including Mount Everest.", factDe: "Nepal liegt im Himalaya zwischen Indien und China und beherbergt acht der zehn höchsten Berge der Welt." },
  { id: "528", difficulty: "medium", en: "Netherlands", de: "Niederlande", factEn: "Located on the North Sea coast of northwestern Europe, roughly a quarter of the Netherlands lies below sea level.", factDe: "Die Niederlande liegen an der Nordsee zwischen Deutschland und Belgien – rund ein Viertel der Landesfläche liegt unter dem Meeresspiegel." },
  { id: "554", difficulty: "easy", en: "New Zealand", de: "Neuseeland", factEn: "New Zealand consists of two main islands—the North Island and South Island—in the southwestern Pacific Ocean.", factDe: "Neuseeland liegt im südwestlichen Pazifik und besteht hauptsächlich aus der Nordinsel und der Südinsel." },
  { id: "558", difficulty: "hard", en: "Nicaragua", de: "Nicaragua", factEn: "Nicaragua is the largest country in Central America and is home to Lake Nicaragua, the region's largest freshwater lake.", factDe: "Nicaragua ist flächenmäßig der größte Staat Mittelamerikas und liegt zwischen Honduras und Costa Rica." },
  { id: "562", difficulty: "hard", en: "Niger", de: "Niger", factEn: "Named after the Niger River, Niger is a vast landlocked country in West Africa covering parts of the Sahara.", factDe: "Der Binnenstaat Niger liegt in Westafrika am Übergang von der Sahelzone zur Sahara." },
  { id: "566", difficulty: "medium", en: "Nigeria", de: "Nigeria", factEn: "Nigeria sits on the Gulf of Guinea in West Africa and is the most populous country on the African continent.", factDe: "Nigeria liegt am Golf von Guinea in Westafrika und ist das bevölkerungsreichste Land des afrikanischen Kontinents." },
  { id: "807", difficulty: "hard", en: "North Macedonia", de: "Nordmazedonien", factEn: "North Macedonia is a landlocked country in the central Balkan Peninsula north of Greece.", factDe: "Nordmazedonien ist ein Binnenstaat auf der südlichen Balkanhalbinsel nördlich von Griechenland." },
  { id: "578", difficulty: "easy", en: "Norway", de: "Norwegen", factEn: "Norway occupies the western and northern portions of the Scandinavian Peninsula along the North Atlantic and Arctic Oceans.", factDe: "Norwegen nimmt den westlichen und nördlichen Teil der Skandinavischen Halbinsel ein." },
  { id: "512", difficulty: "hard", en: "Oman", de: "Oman", factEn: "Oman occupies the southeastern coast of the Arabian Peninsula and controls an exclave on the strategic Strait of Hormuz.", factDe: "Das Sultanat Oman liegt im Südosten der Arabischen Halbinsel am Arabischen Meer und an der Straße von Hormus." },
  { id: "586", difficulty: "medium", en: "Pakistan", de: "Pakistan", factEn: "Pakistan stretches from the Arabian Sea coastline northward to the Karakoram mountain range and K2.", factDe: "Pakistan erstreckt sich vom Arabischen Meer im Süden bis hoch ins Karakorum-Gebirge im Norden." },
  { id: "585", difficulty: "hard", en: "Palau", de: "Palau", factEn: "Palau is an archipelago of more than 300 islands in the western Pacific Ocean east of the Philippines.", factDe: "Palau ist ein Inselstaat aus über 300 Inseln im westlichen Pazifik östlich der Philippinen." },
  { id: "275", difficulty: "hard", en: "Palestine", de: "Palästina", factEn: "The State of Palestine comprises the West Bank (bordering Jordan and the Dead Sea) and the Gaza Strip along the Mediterranean.", factDe: "Palästina umfasst das Westjordanland am Toten Meer sowie den Gazastreifen an der Mittelmeerküste." },
  { id: "591", difficulty: "medium", en: "Panama", de: "Panama", factEn: "Panama forms the narrow land bridge connecting North and South America, pierced by the Panama Canal.", factDe: "Panama bildet die schmale Landbrücke zwischen Mittel- und Südamerika, durch die der Panamakanal führt." },
  { id: "598", difficulty: "hard", en: "Papua New Guinea", de: "Papua-Neuguinea", factEn: "Papua New Guinea occupies the eastern half of the island of New Guinea and hundreds of surrounding islands north of Australia.", factDe: "Papua-Neuguinea nimmt die Osthälfte der Insel Neuguinea nördlich von Australien ein." },
  { id: "600", difficulty: "medium", en: "Paraguay", de: "Paraguay", factEn: "Paraguay is a landlocked country in central South America bisected by the Paraguay River.", factDe: "Paraguay ist ein Binnenstaat im Zentrum Südamerikas zwischen Brasilien, Argentinien und Bolivien." },
  { id: "604", difficulty: "medium", en: "Peru", de: "Peru", factEn: "Peru sits on South America's central Pacific coast and encompasses coastal desert, the high Andes, and Amazon rainforest.", factDe: "Peru liegt an der Pazifikküste Südamerikas und reicht von der Küstenwüste über die Anden bis ins Amazonasbecken." },
  { id: "608", difficulty: "medium", en: "Philippines", de: "Philippinen", factEn: "The Philippines is an archipelago of more than 7,600 islands in the western Pacific Ocean.", factDe: "Die Philippinen sind ein Inselstaat aus über 7.600 Inseln im westlichen Pazifik." },
  { id: "616", difficulty: "easy", en: "Poland", de: "Polen", factEn: "Poland lies in Central Europe between Germany and Belarus/Ukraine, with a northern coastline on the Baltic Sea.", factDe: "Polen liegt in Mitteleuropa zwischen Deutschland und Osteuropa und grenzt im Norden an die Ostsee." },
  { id: "620", difficulty: "easy", en: "Portugal", de: "Portugal", factEn: "Occupying the western side of the Iberian Peninsula, Portugal is the westernmost country of mainland Europe.", factDe: "Portugal liegt im Westen der Iberischen Halbinsel und bildet das westlichste Festlandgebiet Europas." },
  { id: "634", difficulty: "hard", en: "Qatar", de: "Katar", factEn: "Qatar occupies a small peninsula jutting northward into the Persian Gulf from Saudi Arabia.", factDe: "Das Emirat Katar liegt auf einer Halbinsel, die von Saudi-Arabien aus nach Norden in den Persischen Golf ragt." },
  { id: "642", difficulty: "medium", en: "Romania", de: "Rumänien", factEn: "Romania sits in southeastern Europe around the Carpathian Mountains and the lower Danube delta on the Black Sea.", factDe: "Rumänien liegt in Südosteuropa an den Karpaten und an der Mündung der Donau ins Schwarze Meer." },
  { id: "643", difficulty: "easy", en: "Russia", de: "Russland", factEn: "Russia is the largest country in the world by area, spanning Eastern Europe and all of Northern Asia across 11 time zones.", factDe: "Russland ist das flächenmäßig größte Land der Erde und erstreckt sich über Osteuropa und Nordasien hinweg über elf Zeitzonen." },
  { id: "646", difficulty: "hard", en: "Rwanda", de: "Ruanda", factEn: "Known as the 'Land of a Thousand Hills', Rwanda is a small, mountainous landlocked country in East-Central Africa.", factDe: "Ruanda ist ein kleiner, dicht besiedelter Binnenstaat im östlichen Zentralafrika und wird ‚Land der tausend Hügel‘ genannt." },
  { id: "659", difficulty: "hard", en: "Saint Kitts and Nevis", de: "St. Kitts und Nevis", factEn: "Saint Kitts and Nevis is a dual-island nation in the Leeward Islands of the Caribbean and the smallest sovereign state in the Americas.", factDe: "St. Kitts und Nevis ist ein kleiner Doppelinselstaat in der Karibik und flächenmäßig der kleinste Staat Amerikas." },
  { id: "662", difficulty: "hard", en: "Saint Lucia", de: "St. Lucia", factEn: "Saint Lucia is a volcanic island nation in the eastern Caribbean famous for its twin Pitons peaks.", factDe: "Der karibische Inselstaat St. Lucia liegt in den Kleinen Antillen südlich von Martinique." },
  { id: "670", difficulty: "hard", en: "Saint Vincent and the Grenadines", de: "St. Vincent und die Grenadinen", factEn: "Located in the southern Caribbean, this nation consists of the main island of Saint Vincent and a chain of smaller Grenadine islands.", factDe: "Der Inselstaat St. Vincent und die Grenadinen liegt in der östlichen Karibik zwischen St. Lucia und Grenada." },
  { id: "882", difficulty: "hard", en: "Samoa", de: "Samoa", factEn: "Samoa is a Polynesian island country in the South Pacific consisting of two main islands, Savai'i and Upolu.", factDe: "Samoa ist ein polynesischer Inselstaat im Südpazifik und besteht aus den beiden Hauptinseln Savai’i und Upolu." },
  { id: "674", difficulty: "hard", en: "San Marino", de: "San Marino", factEn: "Landlocked inside north-central Italy on the slopes of Mount Titano, San Marino is the world's oldest surviving republic.", factDe: "San Marino liegt als Enklave mitten in Italien am Monte Titano und gilt als älteste bestehende Republik der Welt." },
  { id: "678", difficulty: "hard", en: "São Tomé and Príncipe", de: "São Tomé und Príncipe", factEn: "São Tomé and Príncipe is an island nation in the Gulf of Guinea off the western equatorial coast of Central Africa.", factDe: "São Tomé und Príncipe ist ein kleiner Inselstaat im Golf von Guinea vor der Westküste Zentralafrikas." },
  { id: "682", difficulty: "easy", en: "Saudi Arabia", de: "Saudi-Arabien", factEn: "Saudi Arabia covers the bulk of the Arabian Peninsula, bordered by the Red Sea to the west and the Persian Gulf to the east.", factDe: "Saudi-Arabien nimmt den größten Teil der Arabischen Halbinsel zwischen Rotem Meer und Persischem Golf ein." },
  { id: "686", difficulty: "hard", en: "Senegal", de: "Senegal", factEn: "Senegal sits on Africa's westernmost point at the Cap-Vert peninsula and nearly surrounds The Gambia.", factDe: "Senegal liegt am westlichsten Punkt des afrikanischen Kontinents und umschließt fast vollständig den Staat Gambia." },
  { id: "688", difficulty: "medium", en: "Serbia", de: "Serbien", factEn: "Serbia is a landlocked country at the crossroads of Central and Southeast Europe in the central Balkans.", factDe: "Serbien ist ein Binnenstaat auf der Balkanhalbinsel im Südosten Europas." },
  { id: "690", difficulty: "hard", en: "Seychelles", de: "Seychellen", factEn: "The Seychelles is an archipelago of 115 islands in the Indian Ocean northeast of Madagascar.", factDe: "Die Seychellen sind ein Inselstaat aus 115 Inseln im Indischen Ozean nordöstlich von Madagaskar." },
  { id: "694", difficulty: "hard", en: "Sierra Leone", de: "Sierra Leone", factEn: "Sierra Leone lies on the southwest coast of West Africa between Guinea and Liberia.", factDe: "Sierra Leone liegt an der Atlantikküste Westafrikas zwischen Guinea und Liberia." },
  { id: "702", difficulty: "hard", en: "Singapore", de: "Singapur", factEn: "Singapore is a sovereign island city-state at the southern tip of the Malay Peninsula.", factDe: "Singapur ist ein Insel- und Stadtstaat an der Südspitze der Malaiischen Halbinsel in Südostasien." },
  { id: "703", difficulty: "medium", en: "Slovakia", de: "Slowakei", factEn: "Slovakia is a mountainous, landlocked country in Central Europe dominated by the Carpathian Mountains.", factDe: "Die Slowakei ist ein gebirgiger Binnenstaat in Mitteleuropa zwischen Tschechien, Polen, der Ukraine, Ungarn und Österreich." },
  { id: "705", difficulty: "medium", en: "Slovenia", de: "Slowenien", factEn: "Slovenia sits between Italy, Austria, Hungary, and Croatia, stretching from the Alps to a short Adriatic coastline.", factDe: "Slowenien liegt zwischen den Alpen und der Adria und grenzt an Italien, Österreich, Ungarn und Kroatien." },
  { id: "090", difficulty: "hard", en: "Solomon Islands", de: "Salomonen", factEn: "The Solomon Islands is a Melanesian nation of hundreds of islands in the South Pacific east of Papua New Guinea.", factDe: "Die Salomonen sind ein melanesischer Inselstaat im Südpazifik östlich von Papua-Neuguinea." },
  { id: "706", difficulty: "hard", en: "Somalia", de: "Somalia", factEn: "Occupying the tip of the Horn of Africa, Somalia has the longest coastline on mainland Africa.", factDe: "Somalia bildet die äußerste Spitze am Horn von Afrika und besitzt die längste Küstenlinie auf dem afrikanischen Festland." },
  { id: "710", difficulty: "easy", en: "South Africa", de: "Südafrika", factEn: "Occupying the southern tip of Africa, South Africa has coastlines on both the Atlantic and Indian Oceans.", factDe: "Südafrika liegt an der Südspitze des afrikanischen Kontinents und grenzt sowohl an den Atlantik als auch an den Indischen Ozean." },
  { id: "728", difficulty: "hard", en: "South Sudan", de: "Südsudan", factEn: "Gaining independence in 2011, landlocked South Sudan is the newest sovereign country in the world.", factDe: "Der Binnenstaat Südsudan erlangte 2011 seine Unabhängigkeit vom Sudan und ist der jüngste anerkannte Staat der Erde." },
  { id: "724", difficulty: "easy", en: "Spain", de: "Spanien", factEn: "Spain occupies most of the Iberian Peninsula and also governs the Balearic Islands and Canary Islands.", factDe: "Spanien nimmt den größten Teil der Iberischen Halbinsel ein und umfasst auch die Balearen und die Kanarischen Inseln." },
  { id: "144", difficulty: "medium", en: "Sri Lanka", de: "Sri Lanka", factEn: "Sri Lanka is a teardrop-shaped island nation in the Indian Ocean just off the southeastern tip of India.", factDe: "Sri Lanka ist ein großer Inselstaat im Indischen Ozean südöstlich der Südspitze Indiens." },
  { id: "729", difficulty: "hard", en: "Sudan", de: "Sudan", factEn: "Located in northeast Africa along the Red Sea, Sudan is where the Blue and White Nile rivers meet at Khartoum.", factDe: "Der Sudan liegt im Nordosten Afrikas am Roten Meer – bei der Hauptstadt Khartum fließen Weißer und Blauer Nil zusammen." },
  { id: "740", difficulty: "hard", en: "Suriname", de: "Suriname", factEn: "Located on the northern Atlantic coast of South America, Suriname is the smallest sovereign country on the continent.", factDe: "Suriname liegt an der Nordküste Südamerikas und ist flächenmäßig der kleinste unabhängige Staat des Kontinents." },
  { id: "752", difficulty: "easy", en: "Sweden", de: "Schweden", factEn: "Sweden is the largest of the Nordic countries, occupying the eastern side of the Scandinavian Peninsula.", factDe: "Schweden liegt auf der östlichen Seite der Skandinavischen Halbinsel an der Ostsee." },
  { id: "756", difficulty: "medium", en: "Switzerland", de: "Schweiz", factEn: "Landlocked in Central Europe, Switzerland is famous for the Alps, its four national languages, and long-standing neutrality.", factDe: "Die Schweiz liegt als Alpen-Binnenstaat in Mitteleuropa und hat vier Landessprachen: Deutsch, Französisch, Italienisch und Rätoromanisch." },
  { id: "760", difficulty: "medium", en: "Syria", de: "Syrien", factEn: "Syria lies at the eastern end of the Mediterranean Sea, bordered by Turkey, Iraq, Jordan, Israel, and Lebanon.", factDe: "Syrien liegt am östlichen Mittelmeer und grenzt an die Türkei, den Irak, Jordanien, Israel und den Libanon." },
  { id: "762", difficulty: "hard", en: "Tajikistan", de: "Tadschikistan", factEn: "Tajikistan is a mountainous, landlocked country in Central Asia where the Pamir Mountains cover more than 90% of the land.", factDe: "Tadschikistan ist ein gebirgiger Binnenstaat in Zentralasien – über 90 % des Landes werden vom Pamir-Gebirge geprägt." },
  { id: "834", difficulty: "medium", en: "Tanzania", de: "Tansania", factEn: "Tanzania sits on the Indian Ocean coast of East Africa and is home to Mount Kilimanjaro, Africa's highest peak.", factDe: "Tansania liegt an der ostafrikanischen Küste des Indischen Ozeans und beherbergt mit dem Kilimandscharo den höchsten Berg Afrikas." },
  { id: "764", difficulty: "medium", en: "Thailand", de: "Thailand", factEn: "Thailand sits in the heart of mainland Southeast Asia, bordering the Andaman Sea and the Gulf of Thailand.", factDe: "Thailand liegt im Zentrum Südostasiens und besitzt Küsten an der Andamanensee und am Golf von Thailand." },
  { id: "626", difficulty: "hard", en: "Timor-Leste", de: "Timor-Leste (Osttimor)", factEn: "Timor-Leste occupies the eastern half of the island of Timor in Southeast Asia, northwest of Australia.", factDe: "Timor-Leste (Osttimor) nimmt die östliche Hälfte der Insel Timor nordwestlich von Australien ein." },
  { id: "768", difficulty: "hard", en: "Togo", de: "Togo", factEn: "Togo is a narrow West African country wedged between Ghana and Benin along the Gulf of Guinea.", factDe: "Togo ist ein schmaler westafrikanischer Staat am Golf von Guinea zwischen Ghana und Benin." },
  { id: "776", difficulty: "hard", en: "Tonga", de: "Tonga", factEn: "Tonga is a Polynesian kingdom of more than 170 islands in the South Pacific south of Samoa.", factDe: "Das Königreich Tonga ist ein polynesischer Inselstaat aus über 170 Inseln im Südpazifik." },
  { id: "780", difficulty: "hard", en: "Trinidad and Tobago", de: "Trinidad und Tobago", factEn: "Trinidad and Tobago is the southernmost island nation in the Caribbean, situated just 11 kilometers off Venezuela.", factDe: "Trinidad und Tobago ist der südlichste Inselstaat der Karibik und liegt nur rund elf Kilometer vor der Küste Venezuelas." },
  { id: "788", difficulty: "medium", en: "Tunisia", de: "Tunesien", factEn: "Tunisia is the northernmost country in Africa, jutting into the Mediterranean Sea toward Sicily.", factDe: "Tunesien ist der nördlichste Staat Afrikas und ragt am Kap Angela weit ins Mittelmeer hinein." },
  { id: "792", difficulty: "easy", en: "Turkey", de: "Türkei", factEn: "Straddling the Bosporus strait, Turkey bridges southeastern Europe and western Asia.", factDe: "Die Türkei verbindet über den Bosporus Südosteuropa und Vorderasien zwischen Schwarzem Meer und Mittelmeer." },
  { id: "795", difficulty: "hard", en: "Turkmenistan", de: "Turkmenistan", factEn: "Bordering the Caspian Sea in Central Asia, Turkmenistan is largely covered by the Karakum Desert.", factDe: "Turkmenistan liegt am Kaspischen Meer in Zentralasien und wird zu rund 80 % von der Wüste Karakum bedeckt." },
  { id: "798", difficulty: "hard", en: "Tuvalu", de: "Tuvalu", factEn: "Tuvalu is a remote Polynesian island nation of nine coral atolls midway between Hawaii and Australia.", factDe: "Tuvalu ist ein abgelegener polynesischer Inselstaat aus neun Korallenatollen im Pazifik zwischen Hawaii und Australien." },
  { id: "800", difficulty: "hard", en: "Uganda", de: "Uganda", factEn: "Uganda is a landlocked East African country straddling the equator along the northern shore of Lake Victoria.", factDe: "Uganda ist ein Binnenstaat in Ostafrika am Äquator und grenzt im Süden an den großen Victoriasee." },
  { id: "804", difficulty: "easy", en: "Ukraine", de: "Ukraine", factEn: "Ukraine lies in Eastern Europe along the northern shore of the Black Sea and Sea of Azov.", factDe: "Die Ukraine liegt in Osteuropa am Nordufer des Schwarzen Meeres." },
  { id: "784", difficulty: "medium", en: "United Arab Emirates", de: "Vereinigte Arabische Emirate", factEn: "The UAE is a federation of seven emirates on the southeastern coast of the Persian Gulf.", factDe: "Die Vereinigten Arabischen Emirate sind ein Zusammenschluss von sieben Emiraten am Persischen Golf." },
  { id: "826", difficulty: "easy", en: "United Kingdom", de: "Vereinigtes Königreich", factEn: "Located off the northwestern coast of mainland Europe, the UK comprises Great Britain and Northern Ireland.", factDe: "Das Vereinigte Königreich liegt vor der Nordwestküste Kontinentaleuropas und umfasst Großbritannien sowie Nordirland." },
  { id: "840", difficulty: "easy", en: "United States", de: "Vereinigte Staaten (USA)", factEn: "Spanning central North America from the Atlantic to the Pacific, the U.S. also includes Alaska and Hawaii.", factDe: "Die USA erstrecken sich vom Atlantik bis zum Pazifik und umfassen zusätzlich Alaska und Hawaii." },
  { id: "858", difficulty: "medium", en: "Uruguay", de: "Uruguay", factEn: "Tucked between Brazil and Argentina along the South Atlantic and Río de la Plata, Uruguay is South America's second-smallest nation.", factDe: "Uruguay liegt an der Atlantikküste Südamerikas zwischen Brasilien und Argentinien." },
  { id: "860", difficulty: "hard", en: "Uzbekistan", de: "Usbekistan", factEn: "Surrounded entirely by landlocked countries, Uzbekistan is one of only two doubly landlocked nations in the world.", factDe: "Usbekistan in Zentralasien ist neben Liechtenstein der einzige doppelte Binnenstaat der Erde – alle seine Nachbarn sind ebenfalls Binnenstaaten." },
  { id: "548", difficulty: "hard", en: "Vanuatu", de: "Vanuatu", factEn: "Vanuatu is a Y-shaped archipelago of roughly 80 islands in the South Pacific Ocean.", factDe: "Vanuatu ist ein Y-förmiger Inselstaat aus rund 80 Inseln im Südpazifik östlich von Australien." },
  { id: "336", difficulty: "hard", en: "Vatican City", de: "Vatikanstadt", factEn: "Enclaved within Rome, Italy, Vatican City is the smallest independent state in the world by both area and population.", factDe: "Die Vatikanstadt liegt mitten in Rom und ist nach Fläche wie Einwohnerzahl der kleinste anerkannte Staat der Erde." },
  { id: "862", difficulty: "medium", en: "Venezuela", de: "Venezuela", factEn: "Venezuela sits on the northern coast of South America and is home to Angel Falls, the world's highest uninterrupted waterfall.", factDe: "Venezuela liegt an der Karibikküste Südamerikas und beherbergt mit dem Salto Ángel den höchsten Wasserfall der Erde." },
  { id: "704", difficulty: "medium", en: "Vietnam", de: "Vietnam", factEn: "Vietnam forms an S-shaped strip along the eastern coast of the Indochinese Peninsula on the South China Sea.", factDe: "Vietnam bildet einen langgezogenen Küstenstreifen am Südchinesischen Meer im Osten Südostasiens." },
  { id: "887", difficulty: "hard", en: "Yemen", de: "Jemen", factEn: "Yemen occupies the southwestern corner of the Arabian Peninsula along the Red Sea and the Gulf of Aden.", factDe: "Der Jemen liegt im Südwesten der Arabischen Halbinsel am Roten Meer und am Golf von Aden." },
  { id: "894", difficulty: "hard", en: "Zambia", de: "Sambia", factEn: "Zambia is a landlocked country in southern Africa bordered by eight nations and home to Victoria Falls.", factDe: "Der Binnenstaat Sambia im südlichen Afrika grenzt an acht Nachbarstaaten und beherbergt die Victoriafälle." },
  { id: "716", difficulty: "hard", en: "Zimbabwe", de: "Simbabwe", factEn: "Zimbabwe is a landlocked country in southern Africa situated between the Zambezi and Limpopo rivers.", factDe: "Simbabwe ist ein Binnenstaat im südlichen Afrika zwischen den Flüssen Sambesi und Limpopo." }
];